#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.340654, -0.234242915, -0.017180654999999996], 'basis': [[-0.24388164027652193, -0.18337391418207488, 0.9523107439977658], [0.0, 0.9819610542275773, 0.18908328318565099], [-0.9698050038724451, 0.04611394125218666, -0.23948227259268426]], 'axis': [0.9523107439977658, 0.18908328318565099, -0.23948227259268426], 'zmin': -0.04729470290653726, 'zmax': 0.05683547960453719, 'profiles': [{'outer': [[-0.09562642914823337, -0.026904455857298133], [-0.09862124818648117, -0.01765503542863066], [-0.09907861359415727, -0.008351821317757913], [-0.09658365349257014, 0.00033455966164692454], [-0.09613013361618501, 0.0014820468929695265], [-0.09082162886209504, 0.010054878439425553], [-0.08347450881817343, 0.01732145098736831], [-0.07504831717031293, 0.02260157014047862], [-0.06653871715538476, 0.025462149456098874], [-0.05816393173511601, 0.027259632737377765], [-0.05029929072327908, 0.029671498741198565], [-0.04376907236683275, 0.03487845000429667], [-0.03928855746247633, 0.04428969892992773], [-0.03656689900750982, 0.05618209220292349], [-0.035131454501262614, 0.06827358139006935], [-0.033730605508997334, 0.08680045658952654], [-0.03311036958133904, 0.09220281373651651], [-0.032345109098603886, 0.09555511186613279], [-0.03126492181964382, 0.0975074036142307], [-0.02977246312408503, 0.09843823517808012], [-0.027916264664784418, 0.09874269293818624], [-0.020053704037497944, 0.09813589948728668], [-0.008544321339193361, 0.09633795107626457], [0.007736599860892651, 0.09327937985719834], [0.02627710977123727, 0.08947330324056328], [0.04381397339195106, 0.08556675527094394], [0.05739946709803719, 0.08226017813371969], [0.06646522893377174, 0.07948044436472616], [0.06799458533346164, 0.07851265053289061], [0.06889259342671772, 0.07710374164001885], [0.0693613586690077, 0.07608800891138352], [0.06945782973631118, 0.07394208429477264], [0.0685714286503693, 0.07056587055407], [0.06645927249717053, 0.06548987725102826], [0.05818125653058012, 0.04827213499720261], [0.053155950488665525, 0.03667497799457618], [0.04946510844758923, 0.02454261684502418], [0.04867401891244994, 0.013607912246113192], [0.05210524037596584, 0.005281356219014465], [0.058557670349499574, -0.0011461855664755799], [0.07515057308013913, -0.013165023731569478], [0.08353153164469525, -0.020725619894630246], [0.09032305855861686, -0.029408831031101493], [0.09114867683944315, -0.030701076708484], [0.0944195334745235, -0.039626574294752685], [0.09349308588264252, -0.04880411415311944], [0.08804419747880461, -0.05828927183945695], [0.07910137775498365, -0.06734223621047554], [0.07768451841521035, -0.06855000955048275], [0.06654585988683422, -0.07597535991008073], [0.05585691138802268, -0.08010209308743241], [0.04713428922112197, -0.08006915444484025], [0.04034163920129882, -0.07655291697250492], [0.03503010755148189, -0.07076992487505847], [0.03085977760382053, -0.06421693674004718], [0.02638800825407567, -0.05606513125827307], [0.02368879159135917, -0.05179598103450698], [0.022119030878910425, -0.05014902398014085], [0.0218478230147462, -0.050074058581833815], [0.0213792681198606, -0.051533016714421856], [0.0214116230053494, -0.0542858937198762], [0.02192467668981401, -0.05816663404105775], [0.022939577923946897, -0.06485289940882842], [0.023663387422965823, -0.0724094891248662], [0.02352659585151242, -0.08027965709280696], [0.021813374302034626, -0.08772147477624054], [0.01790487436736761, -0.09404726316417326], [0.011097158015181035, -0.09869226939284169], [0.0011232573742278045, -0.10127052562871182], [-0.010621742460026078, -0.1016223175590741], [-0.022451315341559197, -0.09980893712364458], [-0.032545531923408026, -0.09566185208593372], [-0.039484877715062344, -0.08939617813913442], [-0.04356019699432789, -0.08135228285048697], [-0.04535367828071214, -0.07214081101069728], [-0.045459476114528226, -0.06263798263471053], [-0.04448424975577554, -0.05376771765823255], [-0.04313248534763715, -0.04592781295374105], [-0.04213341893570958, -0.03957356574236706], [-0.04227697571821397, -0.03570740708730636], [-0.04415871221720864, -0.03510520991328936], [-0.04745037957092049, -0.036938838773070894], [-0.051689721741866576, -0.04007189177012717], [-0.05685151609122694, -0.04333731545244376], [-0.06297148872698097, -0.045810452008772505], [-0.06972161357042193, -0.04680010428034303], [-0.07655573646609337, -0.04579220437762768], [-0.08324316358993364, -0.04227705793583257], [-0.08463587580431392, -0.040996942257740907], [-0.09060515975080202, -0.03506201022346076]], 'holes': []}], 'simplify_tolerance': 4.0073002099452076e-05, 'sketch_entity_count': 90}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
